#include <stdint.h>

static int32_t pw_hash(char *p) {
    uint32_t h = 0x1505;
    while (*p) {
        h = (h << 5) + h + (unsigned char)*p;
        p++;
    }
    return (int32_t)h;
}

int32_t check_pw(char *p) {
    return pw_hash(p) == 0x1f33e35f;
}
